324: // checkIPAMUsage reads Calico IPAMBlock and IPPool CRDs to compute per-block utilisation
325: // and discover disabled pools.
326: // Returns (usageByBlock, exhaustedBlocks, disabledPools, error).
327: func (m *CNIModule) checkIPAMUsage(ctx context.Context) (map[string]float64, []string, []string, error) {
328: 	// 1. Check IPPools for disabled status
329: 	poolList := &unstructured.UnstructuredList{}
330: 	poolList.SetGroupVersionKind(schema.GroupVersionKind{
331: 		Group:   calicoCRDGroup,
332: 		Version: "v1",
333: 		Kind:    "IPPoolList",
334: 	})
335: 	var disabledPools []string
336: 	if err := m.Client.List(ctx, poolList); err == nil {
337: 		for _, item := range poolList.Items {
338: 			disabled, _, _ := unstructured.NestedBool(item.Object, "spec", "disabled")
339: 			if disabled {
340: 				disabledPools = append(disabledPools, item.GetName())
341: 			}
342: 		}
343: 	}
344: 
345: 	// 2. Check IPAMBlocks for capacity and usage
346: 	blockList := &unstructured.UnstructuredList{}
347: 	blockList.SetGroupVersionKind(schema.GroupVersionKind{
348: 		Group:   calicoCRDGroup,
349: 		Version: "v1",
350: 		Kind:    "IPAMBlockList",
351: 	})
352: 	if err := m.Client.List(ctx, blockList); err != nil {
353: 		return nil, nil, disabledPools, fmt.Errorf("list IPAMBlocks: %w", err)
354: 	}
355: 
356: 	usageByPool := make(map[string]float64)
357: 	var exhausted []string
358: 
359: 	for _, item := range blockList.Items {
360: 		cidr, _, _ := unstructured.NestedString(item.Object, "spec", "cidr")
361: 		if cidr == "" {
362: 			continue
363: 		}
364: 		allocations, _, _ := unstructured.NestedSlice(item.Object, "spec", "allocations")
365: 		unallocated, _, _ := unstructured.NestedSlice(item.Object, "spec", "unallocated")
366: 
367: 		total := len(allocations) + len(unallocated)
368: 		if total == 0 {
369: 			continue
370: 		}
371: 
372: 		used := 0
373: 		for _, a := range allocations {
374: 			if a != nil {
375: 				used++
376: 			}
377: 		}
378: 
379: 		pct := float64(used) / float64(total) * 100
380: 		usageByPool[cidr] = pct
381: 		if pct >= 100 {
382: 			exhausted = append(exhausted, cidr)
383: 		}
384: 	}
385: 	return usageByPool, exhausted, disabledPools, nil
386: }
